<script lang="ts">
	import { libraryIdentity, libraryViewKey, localLibraryState, captureLibraryView, captureLibraryContext, assertLibraryContext } from "$localLibrary/library";
	import { nativeAuthority } from "$platform/mutation-authority";
	import { createFeedContinuation } from "$platform/feed-continuation";
	import { captureNavigationEpoch, sameNavigationEpoch } from "$platform/navigation-authority";
	import { Button } from "$lib/components/ui/button";
	import { replaceState } from "$app/navigation";
	import { page } from "$app/state";
	import { API, Constants } from "$lib";
	import * as Empty from "$lib/components/ui/empty";
	import Grid from "$lib/components/ui/Grid.svelte";
	import { setReadHistory } from "$lib/Context";
	import type { HTTPResponse } from "$lib/HTTP";
	import { Session } from "$lib/stores";
	import { StatusCodes } from "http-status-codes";
	import { onDestroy, onMount, tick } from "svelte";
	import { toast } from "svelte-sonner";
	import { writable } from "svelte/store";
	import ChapterFeedMangaEntry from "./ChapterFeedMangaEntry.svelte";
	import ErrorComponent from "./ErrorComponent.svelte";
	import GenericPagination from "./GenericPagination.svelte";
	import { Spinner } from "./ui/spinner";

	const {
		onSearch
	}: {
		onSearch: (n?: number) => Promise<HTTPResponse<MappedChapterFeedResponse>> | undefined;
	} = $props();

	const readHistory = writable<Record<string, Record<string, null>> | undefined>();
	setReadHistory(readHistory);

	let feed = $state<MappedChapterFeedResponse>();
	let entries = $state<Manga[]>([]);
	let idMap = $state<Record<string, undefined>>({});

	const isPrivateFeed = ["/library", "/history"].some(prefix => window.location.pathname.startsWith(prefix));
	const isEntity =
		window.location.pathname.startsWith("/user") ||
		window.location.pathname.startsWith("/author") ||
		window.location.pathname.startsWith("/group");
	let isMounted = $state(false);
	let isLoading = $state(false);
	let footerRef = $state<HTMLElement>();
	let error = $state<Constants.Error.Error>();
	let historyGeneration = 0, historyDisposed = false, feedGeneration = 0;
	let paginationPaused = $state(false), paginationFailed = $state(false);
	let continuation: ReturnType<typeof createFeedContinuation> | undefined;
	onDestroy(() => { historyDisposed = true; historyGeneration++; feedGeneration++; pendingPrivateRead = undefined; releaseReadWaiters(); continuation?.dispose(); readHistory.set(undefined); });
	$effect(() => {
		const view = $libraryViewKey, ids = entries.map(row => row.id), allowed = $libraryIdentity.canUse;
		const generation = ++historyGeneration; readHistory.set(undefined);
		if (!allowed || !ids.length || historyDisposed) return;
		const query = new URLSearchParams(); ids.forEach(id => query.append("id", id));
		void API.ChapterHistory.Search(query).then(res => {
			if (!historyDisposed && generation === historyGeneration && captureLibraryView() === view && res?.status === StatusCodes.OK && res.body) readHistory.set(res.body);
		}).catch(() => { if (!historyDisposed && generation === historyGeneration) readHistory.set(undefined); });
	});

	onMount(async () => {
		if (isPrivateFeed) { isMounted = true; return; }
		const initialHref = window.location.href;
		const state = page.state as {
			_$ChapterFeed_history: typeof $readHistory;
			_$ChapterFeed_feed: typeof feed;
			_$ChapterFeed_entries: typeof entries;
			_$ChapterFeed_context?: string;
		};

		if (!["/library", "/history"].some(prefix => window.location.pathname.startsWith(prefix)) && state._$ChapterFeed_feed && state._$ChapterFeed_entries && state._$ChapterFeed_context === window.location.href) {
			$readHistory = undefined;
			feed = state._$ChapterFeed_feed;
			entries = state._$ChapterFeed_entries;
		} else {
			const p = page.url.searchParams.get("page");
			await load(p ? Number(p) : undefined);
		}
		if (!historyDisposed) {
			if (!feed && !error && window.location.href === initialHref) error = new Constants.Error.Error("Feed load interrupted", "The previous route request no longer belongs to the current view. Retry the current feed.");
			isMounted = true;
		}
	});

	const load = async (n?: number) => {
		if (isLoading || historyDisposed) return false;
		const { pathname } = window.location, href = window.location.href, search = onSearch;
		const context = isPrivateFeed ? captureLibraryContext() : undefined, view = isPrivateFeed ? captureLibraryView() : undefined;
		const navigation = captureNavigationEpoch(), generation = ++feedGeneration;
		const owned = () => {
			if (historyDisposed || generation !== feedGeneration || href !== window.location.href || search !== onSearch || !sameNavigationEpoch(navigation)) return false;
			if (context) { try { assertLibraryContext(context); if (captureLibraryView() !== view) return false; } catch { return false; } }
			return true;
		};
		isLoading = true;
		try {
			const res = await onSearch(n);
			if (!owned()) return false;

			if (res?.status === StatusCodes.OK && res.body) {
				const next = res.body;
				if (!Number.isSafeInteger(next.page) || next.page < 1 || !Number.isSafeInteger(next.limit) || next.limit < 1 || !Number.isSafeInteger(next.total) || next.total < 0 || !Array.isArray(next.data) || (n !== undefined && next.page !== n)) throw new Constants.Error.Error("Feed pagination stopped", "The server returned an invalid or nonadvancing page. Existing updates remain available; retry only after checking the current feed.");
				if (feed && n !== undefined && next.data.length) {
					const known = new Set(entries.flatMap(manga => manga.relationships._chapters?.map(chapter => chapter.id) ?? []));
					if (next.data.every(chapter => known.has(chapter.id))) throw new Constants.Error.Error("Feed pagination stopped", "The next page repeated only existing chapters. No automatic requests will continue; retry or reload the current feed.");
				}
				if (!next.data.length && next.limit * (next.page - 1) < next.total) throw new Constants.Error.Error("Feed pagination stopped", "The server returned an empty page before its reported end. Previous acknowledged updates are retained; retry or reload the current feed.");
				feed = next;
				// Feed and accumulated entries are committed together only after append.

				if (feed.data) {
					const newEntries: Record<string, Manga> = {};
					const newIds = [];

					for (const chapter of feed.data) {
						const id = chapter.relationships.manga.id;
						let manga = newEntries[id] ?? feed.map.manga[id];

						if (!(id in newEntries)) {
							newEntries[id] = manga;
							entries.push(manga);
						}

						if (!(id in idMap)) {
							idMap[id] = undefined;
							if ($libraryIdentity.canUse) newIds.push(id);
						}

						if (!manga.relationships._chapters) manga.relationships._chapters = [];
						if (!manga.relationships._chapters.some(e => e.id === chapter.id)) {
							manga.relationships._chapters.push(chapter);
						}
					}

					entries = entries;
					const acknowledgedEntries = $state.snapshot(entries);
					const acknowledgedManga: Record<string, Manga> = {}, acknowledgedChapters = new Map<string, Chapter>();
					for (const manga of acknowledgedEntries) {
						const previous = acknowledgedManga[manga.id], chapters = new Map<string, Chapter>();
						for (const chapter of [...(previous?.relationships._chapters ?? []), ...(manga.relationships._chapters ?? [])]) { chapters.set(chapter.id, chapter); acknowledgedChapters.set(chapter.id, chapter); }
						acknowledgedManga[manga.id] = { ...manga, relationships: { ...manga.relationships, _chapters: [...chapters.values()] } };
					}
					if (!isPrivateFeed) replaceState(href, {
						...page.state,
						_$ChapterFeed_feed: { ...$state.snapshot(feed), data: [...acknowledgedChapters.values()], map: { ...$state.snapshot(feed.map), manga: acknowledgedManga } },
						_$ChapterFeed_entries: acknowledgedEntries,
						_$ChapterFeed_context: href
					});

					// Private read flags are loaded by the selected-library effect below.
				}
				return true;
			} else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) {
				throw Constants.Error.TooManyRequests;
			} else throw Constants.Error.Unknown;
		} catch (e) {
			if (!owned()) return false;
			if (isMounted && feed) {
				if (e instanceof Constants.Error.Error) toast.error(e.title, { description: e.body });
				else {
					console.error(e);
					toast.error(Constants.Error.Unknown.title, { description: Constants.Error.Unknown.body });
				}
			} else {
				if (e instanceof Constants.Error.Error) error = e;
				else {
					console.error(e);
					error = Constants.Error.Unknown;
				}
			}
			return false;
		} finally {
			if (generation === feedGeneration && !historyDisposed) isLoading = false;
			releaseReadWaiters();
		}
	};

	let privateRequestKey = "", privateSearch: typeof onSearch | undefined, privateDraining = false;
	let pendingPrivateRead: { href: string; navigation: number; search: typeof onSearch } | undefined;
	const readWaiters = new Set<() => void>();
	function releaseReadWaiters() { for (const resolve of readWaiters) resolve(); readWaiters.clear(); }
	const waitForReadIdle = () => isLoading ? new Promise<void>(resolve => readWaiters.add(resolve)) : Promise.resolve();
	async function drainPrivateReads() {
		if (privateDraining || historyDisposed) return;
		privateDraining = true;
		try {
			while (pendingPrivateRead && !historyDisposed) {
				await waitForReadIdle();
				if (historyDisposed) return;
				const request = pendingPrivateRead; pendingPrivateRead = undefined;
				if (!request || request.href !== window.location.href || request.search !== onSearch || !sameNavigationEpoch(request.navigation)) continue;
				const value = new URL(request.href).searchParams.get("page");
				await load(value ? Number(value) : undefined);
				if (!historyDisposed && !pendingPrivateRead && !feed && !error && request.href === window.location.href) error = new Constants.Error.Error("Feed load interrupted", "The personal feed changed while loading. Retry the currently selected library; no previous account rows are displayed.");
			}
		} finally { privateDraining = false; }
	}
	function queuePrivateRead() {
		if (historyDisposed) return;
		pendingPrivateRead = { href: window.location.href, navigation: captureNavigationEpoch(), search: onSearch };
		// Clear old personal DTOs synchronously, before any latest-context read.
		feed = undefined; entries = []; idMap = {}; readHistory.set(undefined); error = undefined; paginationPaused = false;
		void Promise.resolve().then(drainPrivateReads);
	}
	$effect.pre(() => {
		if (!isPrivateFeed || !isMounted || !$localLibraryState.ready || historyDisposed) return;
		const view = $libraryViewKey, authority = $nativeAuthority, href = page.url.href, search = onSearch;
		const context = captureLibraryContext(), key = JSON.stringify([view, authority.actor, authority.epoch, context.generation, context.key, href]);
		if (key === privateRequestKey && search === privateSearch) return;
		privateRequestKey = key; privateSearch = search; queuePrivateRead();
	});
	async function retryFeed() {
		if (historyDisposed || isLoading) return;
		if (isPrivateFeed) { queuePrivateRead(); return; }
		const href = window.location.href; error = undefined;
		const value = new URL(href).searchParams.get("page");
		await load(value ? Number(value) : undefined);
		if (!historyDisposed && !feed && !error && href === window.location.href) error = new Constants.Error.Error("Feed load interrupted", "The route changed while loading. Retry the current feed.");
	}

	$effect(() => {
		const target = footerRef;
		if (!target || isEntity) return;
		continuation = createFeedContinuation({
			target, isAlive: () => !historyDisposed && footerRef === target,
			getFeed: () => feed, loadPage: load, settle: tick,
			captureContext: () => { const context = isPrivateFeed ? captureLibraryContext() : undefined, view = isPrivateFeed ? captureLibraryView() : undefined, navigation = captureNavigationEpoch(), href = window.location.href, search = onSearch; return () => { if (historyDisposed || footerRef !== target || href !== window.location.href || onSearch !== search || !sameNavigationEpoch(navigation)) return false; if (context) { try { assertLibraryContext(context); if (captureLibraryView() !== view) return false; } catch { return false; } } return true; }; },
			pause: (paused, failed) => { if (!historyDisposed) { paginationPaused = paused; paginationFailed = failed; } }
		});
		const owner = continuation;
		return () => { owner.dispose(); if (continuation === owner) continuation = undefined; };
	});
</script>

{#if error}
	<ErrorComponent {error} />
	{#if !isEntity}
		<Button variant="outline" disabled={isLoading} onclick={retryFeed}>Retry feed</Button>
	{/if}
{:else if isMounted && feed}
	{#if entries.length}
		<Grid class="gap-x-4" breakpoints={isEntity ? { 0: 2, 1080: 1 } : { 0: 3, 1400: 2, 1080: 1 }}>
			{#each entries as manga (manga)}
				<ChapterFeedMangaEntry {manga} />
			{/each}
		</Grid>
		{#if feed && (isEntity ? (feed.total > feed.limit || feed.page > 1) : feed.limit * feed.page < feed.total)}
			{#if isEntity}
				<footer>
					<GenericPagination {feed} />
				</footer>
			{:else}
				<footer class:h-0.5={!isLoading} bind:this={footerRef}>
					{#if isLoading}
						<Empty.Root>
							<Spinner class="size-10" />
						</Empty.Root>
					{/if}
					{#if paginationPaused}
						<Button variant="outline" class="w-full" disabled={isLoading} onclick={() => continuation?.resume()}>{paginationFailed ? "Retry loading updates" : "Load more updates"}</Button>
					{/if}
				</footer>
			{/if}
		{/if}
	{:else}
		<Empty.Root>
			<Empty.Header>
				<Empty.Title>No results found</Empty.Title>
				<Empty.Description>
					{#if window.location.search}
						Try adjusting your search or using different keywords.
					{:else if window.location.pathname.startsWith("/library")}
						<p>The database may still be updating, or you haven't added anything to your library yet.</p>
						<br />
						<p>Any chapters from titles you add to your library will appear here shortly.</p>
					{:else if window.location.pathname.startsWith("/history")}
						<p>The database may still be updating, or you haven't read anything yet.</p>
						<br />
						<p>Any chapters you read will appear here shortly.</p>
					{:else}
						The database may still be updating, or no entries matching your filters were found.
					{/if}
				</Empty.Description>
			</Empty.Header>
		</Empty.Root>
	{/if}
	{#if isEntity && !entries.length && (feed.total > feed.limit || feed.page > 1)}
		<footer>
			<GenericPagination {feed} />
		</footer>
	{/if}
{:else}
	<Empty.Root>
		<Spinner class="size-10" />
	</Empty.Root>
{/if}
